import{_ as s,o as i,c as u,a3 as t,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/gruppenprozesse-ausweisnummern-automatisch-generieren.png",w=JSON.parse('{"title":"Ausweisnummern automatisch vergeben","description":"","frontmatter":{"title":"Ausweisnummern automatisch vergeben","source_pageid":433,"source_revision":5336},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/ausweisnummern-automatisch-generieren-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/ausweisnummern-automatisch-generieren-gruppenprozesse-allgemein.md"}'),m={name:"schild3/suchen-gruppenprozesse/ausweisnummern-automatisch-generieren-gruppenprozesse-allgemein.md"};function o(l,r,p,c,d,h){return i(),u("div",null,[...r[0]||(r[0]=[t('<h1 id="ausweisnummern-automatisch-vergeben" tabindex="-1">Ausweisnummern automatisch vergeben <a class="header-anchor" href="#ausweisnummern-automatisch-vergeben" aria-label="Permalink to &quot;Ausweisnummern automatisch vergeben&quot;">​</a></h1><p>Erzeugen Sie Ausweisnummern für die ausgewählte Schülergruppe. Entscheiden Sie, ob vorhandene Nummern erhalten bleiben und ob frei gewordene Nummern erneut verwendet werden.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-ausweisnummern-automatisch-generieren.png"><img src="'+a+'" alt="Generiere Ausweisnummern per Gruppenprozess." loading="lazy"></a></p><p><em>Generiere Ausweisnummern per Gruppenprozess.</em></p><p>Um Ausweisnummern für Schüler zu generieren, kann der Gruppenprozess <em>Ausweisnummern automatisch generieren</em> gewählt werden.</p><p><strong>Vorhandene und frei gewordene Nummern behandeln</strong></p><p>Ist der Haken bei <strong>Vorhandene Nummern der Gruppe zuvor löschen</strong> gesetzt, bekommen die Schüler neue Nummern. Ansonsten werden vorhandene Nummern beibehalten und nur leere Felder werden befüllt.</p><p><strong>Nicht mehr benötigte Nummern &quot;wiederverwenden&quot;</strong> nutzt von nicht mehr vorhandenen oder abgegangenen Schülern die Nummern erneut, so dass ein Nummernbereich ausreichend ist, welcher der Schülerzahl entspricht.</p>',8),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Beachten Sie hierzu, dass die Startnummer für die Ausweise über "),e("em",null,[n('Verwaltung ➜ Einstellungen ➜ Allgemeines ➜ Sonstiges" und dann mit '),e("strong",null,"Beginn Nummernbereich für Ausweisnummern"),n(" eingestellt werden kann.")])]),e("p",null,'Somit ließen sich zum Beispiel Schülerausweisnummern mit "30000" beginnen, so dass alle "30.000er-Nummern" klar Schülern zugeordnet wären.')],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Ausweisnummern_automatisch_generieren_(Gruppenprozesse_Allgemein)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 5336.")],-1)])])}const b=s(m,[["render",o]]);export{w as __pageData,b as default};
